import { useEffect } from 'react';
import { useIntl } from 'react-intl';
import { useSearchParams } from 'react-router-dom';

import { BasicContainer } from 'components';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { useGoogleAnalytics } from 'hooks';

import { CompetitionSelector, CupSection, LeagueSection } from './components';
import { TEMP_HIDE_COMPETITION_SELECTOR } from './constants';

const COMPETITION_TYPE_PARAM = 'competition-type';
const LEAGUE_TYPE_PARAM = 'league-type';
const COMPETITION_TYPES = ['league', 'cup'] as const;
const LEAGUE_TYPES = ['super-league', 'premier-league'] as const;

type CompetitionType = (typeof COMPETITION_TYPES)[number];
type LeagueType = (typeof LEAGUE_TYPES)[number];

const parseCompetitionType = (value: string | null): CompetitionType =>
  COMPETITION_TYPES.includes(value as CompetitionType)
    ? (value as CompetitionType)
    : 'league';

const parseLeagueType = (value: string | null): LeagueType =>
  LEAGUE_TYPES.includes(value as LeagueType)
    ? (value as LeagueType)
    : 'super-league';

interface RankingsProps {
  dataTestId?: string;
}

export const Rankings: React.FC<RankingsProps> = ({ dataTestId }) => {
  useDataRefreshForTab('Growth League - Ranking');
  const [searchParams, setSearchParams] = useSearchParams();
  const trackGA = useGoogleAnalytics();

  const competitionType = parseCompetitionType(
    searchParams.get(COMPETITION_TYPE_PARAM),
  );
  const leagueType = parseLeagueType(searchParams.get(LEAGUE_TYPE_PARAM));

  const { formatMessage } = useIntl();
  const shouldHideCompetitionSelector = TEMP_HIDE_COMPETITION_SELECTOR === true;
  const shouldShowLeagueSection =
    shouldHideCompetitionSelector || competitionType === 'league';
  const shouldShowCupSection =
    shouldHideCompetitionSelector === false && competitionType === 'cup';

  useEffect(() => {
    const next = new URLSearchParams(searchParams);
    let changed = false;

    const competitionParam = searchParams.get(COMPETITION_TYPE_PARAM);
    if (!COMPETITION_TYPES.includes(competitionParam as CompetitionType)) {
      next.set(COMPETITION_TYPE_PARAM, 'league');
      changed = true;
    }

    const resolvedCompetition = parseCompetitionType(
      next.get(COMPETITION_TYPE_PARAM),
    );
    if (resolvedCompetition === 'league') {
      const leagueParam = next.get(LEAGUE_TYPE_PARAM);
      if (!LEAGUE_TYPES.includes(leagueParam as LeagueType)) {
        next.set(LEAGUE_TYPE_PARAM, 'super-league');
        changed = true;
      }
    }

    if (changed) {
      setSearchParams(next, { replace: true });
    }
  }, [searchParams, setSearchParams]);

  const handleCompetitionTypeChange = (value: string) => {
    const nextCompetitionType = parseCompetitionType(value);

    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set(COMPETITION_TYPE_PARAM, nextCompetitionType);

      if (nextCompetitionType === 'cup') {
        next.delete(LEAGUE_TYPE_PARAM);
      }

      return next;
    });

    trackGA({
      event_category: 'Content',
      event_action: 'Content',
      event_label: nextCompetitionType,
    });
  };

  const handleLeagueTypeChange = (value: string) => {
    const nextLeagueType = parseLeagueType(value);

    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set(COMPETITION_TYPE_PARAM, competitionType);
      next.set(LEAGUE_TYPE_PARAM, nextLeagueType);
      return next;
    });

    trackGA({
      event_category: 'Filter',
      event_action: 'Select',
      event_label: nextLeagueType,
    });
  };

  return (
    <BasicContainer
      dataTestId={dataTestId ? `${dataTestId}-rankings` : undefined}
      header={{
        title: formatMessage({
          id: 'ValueCreation.GrowthLeague.Rankings.rankingBreakdown',
          defaultMessage: '',
        }),
        titleSize: 'H2',
        rightContent: shouldHideCompetitionSelector ? undefined : (
          <CompetitionSelector
            dataTestId={dataTestId ? `${dataTestId}-rankings` : undefined}
            competitionType={competitionType}
            setCompetitionType={handleCompetitionTypeChange}
          />
        ),
      }}
    >
      {shouldShowLeagueSection && (
        <LeagueSection
          dataTestId={dataTestId ? `${dataTestId}-rankings` : undefined}
          leagueType={leagueType}
          setLeagueType={handleLeagueTypeChange}
        />
      )}
      {shouldShowCupSection && (
        <CupSection
          dataTestId={dataTestId ? `${dataTestId}-rankings` : undefined}
        />
      )}
    </BasicContainer>
  );
};
